 const [learning,setLearning]=useState(()=>initial.current?.learning||{});
 const [studyLog,setStudyLog]=useState(()=>initial.current?.studyLog||[]);
 const studyClock=useRef({key:'',ms:0,last:Date.now(),active:false});
 const [libraryPage,setLibraryPage]=useState(0),[codexTab,setCodexTab]=useState('招式'),[view,setView]=useState('home'),[modal,setModal]=useState(null),[questions,setQuestions]=useState([]),[manifest,setManifest]=useState(null),[loadError,setLoadError]=useState('');
 const [practiceContext,setPracticeContext]=useState(null);
 const [toast,setToast]=useState(''),[feedback,setFeedback]=useState(null),[target,setTarget]=useState(0),[selectedNode,setSelectedNode]=useState(null),[burst,setBurst]=useState(0),[search,setSearch]=useState(''),[filter,setFilter]=useState('全部'),[onlyWrong,setOnlyWrong]=useState(false),[practice,setPractice]=useState(null),[practiceResult,setPracticeResult]=useState(null),[trainingCount,setTrainingCount]=useState(0);
 const startTime=useRef(Date.now());const inputFile=useRef();const timer=useRef();
 useEffect(()=>{setLibraryPage(0);},[filter,onlyWrong,search]);
 const qIndex=useMemo(()=>new Map(questions.map(q=>[q.id,q])),[questions]);
 const categories=useMemo(()=>[...new Set(questions.map(q=>q.category))].sort(),[questions]);
 const notify=t=>{setToast(t);clearTimeout(timer.current);timer.current=setTimeout(()=>setToast(''),3500);};
 useEffect(()=>{let live=true;const get=async url=>{const r=await fetch(url);if(!r.ok)throw Error('题库载入失败（'+r.status+'），请刷新重试。');return url.endsWith('.gz')?decodeQuestionData(await r.arrayBuffer()):r.json();};(async()=>{const m=await get('/data/manifest.json').catch(()=>null);if(live)setManifest(m);let files=m?.questionFiles;let index;if(!files?.length){index=await get('/data/questions.json');if(Array.isArray(index)){const reviews=m?.answerReviewFile?await get(m.answerReviewFile):[];if(live)setQuestions(applyQuestionReviews(index,reviews));return;}files=index.files;}if(!files?.length)throw Error('题库索引尚未就绪，请刷新重试。');const all=[];for(let i=0;i<files.length;i+=4){const parts=await Promise.all(files.slice(i,i+4).map(get));all.push(...parts.flatMap(p=>Array.isArray(p)?p:p.questions||[]));if(!live)return;}const reviews=m?.answerReviewFile?await get(m.answerReviewFile):[];if(live){setQuestions(applyQuestionReviews(all,reviews));setLoadError('');}})().catch(e=>{if(live)setLoadError(e.message);});return()=>{live=false;};},[]);
 useEffect(()=>{let alive=true;loadSnapshot(initial.current).then(data=>{if(!alive)return;if(data){setProfile(data.profile);setRun(data.run||null);setSettings(data.settings||{sound:false,motion:true});setLearning(data.learning||{});setStudyLog(data.studyLog||[]);}setStorageReady(true);});return()=>{alive=false;};},[]);
 useEffect(()=>{if(!storageReady)return;saveSnapshot({version:1,profile,run,settings,learning,studyLog}).then(ok=>{if(!ok)notify('设备储存空间不足，请导出存档备份。');});},[storageReady,profile,run,settings,learning,studyLog]);
 useEffect(()=>{setAudio(settings.sound);document.documentElement.dataset.motion=settings.motion?'on':'off';},[settings]);
 useEffect(()=>{if(run?.state==='battle'&&run.battle?.phase==='question'&&!run.uiQuestionId&&questions.length){const copy=structuredClone(run);const used=new Set(run.answers.map(a=>a.questionId));const valid=questions.filter(q=>q.usable!==false&&hasScorableAnswer(q)&&q.options.length>=2);let pool=valid.filter(q=>!used.has(q.id));if(!pool.length)pool=valid;if(!pool.length)return;const categoryPool=pool.filter(q=>run.uiCategory?q.category===run.uiCategory:run.act===1?(/类比|定义/.test(q.category)):true);if(categoryPool.length)pool=categoryPool;const random=Engine.rng(`${run.seed}-${run.answers.length}-${run.uiCategory||''}`);const unseen=pool.filter(q=>!learning[q.id]||learning[q.id].correct<learning[q.id].attempts);const q=random.pick(unseen.length?unseen:pool);copy.uiQuestionId=q.id;Engine.selectQuestion(copy,q.id);startTime.current=Date.now();setRun(copy);}},[run,questions]);
 useEffect(()=>{if(run&&['victory','defeat'].includes(run.state)&&!run.settled){const r=structuredClone(run),p=structuredClone(profile);Engine.settleRun(r,p);setRun(r);setProfile(p);sfx('reward');}},[run]);
 const mutate=(fn,...args)=>{if(!run)return;const r=structuredClone(run);fn(r,...args);setRun(r);return r;};
 const act=(fn,...args)=>{const r=mutate(fn,...args);sfx('click');if(r){const newer=r.achievements.filter(id=>!run.achievements.includes(id));if(newer.length)notify(`铭记达成：${find(ACHIEVEMENTS,newer[0])?.name}`);}if(r&&r.state!==run.state){setFeedback(null);setTarget(0);if(r.state==='reward'||r.state==='treasure')sfx('reward');}return r;};
 const record=(q,option,correct,elapsed,mode='battle')=>{if(q.usable===false||!hasScorableAnswer(q))return;setStudyLog(log=>[...log,{id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,questionId:q.id,module:q.module,category:q.category,topic:q.topic,correct,elapsed,at:Date.now(),mode,exam:q.exam,year:q.year}]);setLearning(l=>{const old=l[q.id]||{attempts:0,correct:0,streak:0};return {...l,[q.id]:{...old,attempts:old.attempts+1,correct:old.correct+(correct?1:0),streak:correct?old.streak+1:0,lastCorrect:correct,lastOption:option,lastTime:Date.now(),elapsed,totalTime:(old.totalTime||0)+elapsed}};});};
 const answer=option=>{const q=qIndex.get(run.uiQuestionId);if(!q||run.battle.phase!=='question')return;const elapsed=getElapsed(),correct=answerMatches(q,option),expected=answerIndices(q),recordedAnswer=expected.length>1?expected:q.answer;record(q,option,correct,elapsed);mutate(Engine.answerQuestion,{correct,questionId:q.id,option,answer:recordedAnswer,elapsed,category:q.module==='资料分析'?'quant':'reasoning'});setFeedback({qId:q.id,selected:option,correct,elapsed});sfx(correct?'correct':'wrong');setBurst(b=>b+1);};
