 const mastered=Object.values(learning).filter(x=>x.streak>=2).length;const answered=Object.values(learning).reduce((n,x)=>n+x.attempts,0);const correct=Object.values(learning).reduce((n,x)=>n+x.correct,0);const wrongIds=Object.keys(learning).filter(id=>!learning[id].lastCorrect);
