 const nextPractice=()=>{const all=practiceContext?.ids?practiceContext.ids.map(id=>qIndex.get(id)).filter(Boolean):practicePool;if(!all.length){notify('当前筛选下没有题目。');return;}if(practiceContext?.order==='sequential'){const i=all.findIndex(q=>q.id===practice?.id);startPractice(all[(i+1)%all.length],practiceContext,true);return;}const pool=all.filter(q=>q.id!==practice?.id);startPractice((pool.length?pool:all)[Math.floor(Math.random()*(pool.length||all.length))],practiceContext,true);};
